CREATE OR ALTER PROCEDURE [dbo].[uspStockCount_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @WarehouseId UNIQUEIDENTIFIER = NULL
	, @CountType NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @ResponsibleEmployeeId UNIQUEIDENTIFIER = NULL
	, @CountNumber NVARCHAR(MAX) = NULL
	, @CountDate DATETIME = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[WarehouseId]
			, j1.[Name] AS [WarehouseName]
			, t.[CountType]
			, t.[CountDate]
			, t.[Status]
			, t.[ApprovedBy]
			, t.[ApprovedAt]
			, t.[Note]
			, t.[CountNumber]
			, t.[ResponsibleEmployeeId]
			, t.[CreatedDate]
		FROM [dbo].[StockCount] AS t
		LEFT JOIN [dbo].[Warehouse] AS j1 ON j1.[Id] = t.[WarehouseId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[CountNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@WarehouseId IS NULL OR t.[WarehouseId] = @WarehouseId)
			AND (ISNULL(@CountType, '') = '' OR t.[CountType] = @CountType)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@ResponsibleEmployeeId IS NULL OR t.[ResponsibleEmployeeId] = @ResponsibleEmployeeId)
			AND (ISNULL(@CountNumber, '') = '' OR t.[CountNumber] LIKE CONCAT('%', @CountNumber, '%'))
			AND (@CountDate IS NULL OR t.[CountDate] = @CountDate)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'warehouseId' THEN r.[WarehouseId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'warehouseName' THEN r.[WarehouseName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'warehouseName' THEN r.[WarehouseName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'countType' THEN r.[CountType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'countType' THEN r.[CountType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'countDate' THEN r.[CountDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'countDate' THEN r.[CountDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvedBy' THEN r.[ApprovedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvedBy' THEN r.[ApprovedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'approvedAt' THEN r.[ApprovedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'approvedAt' THEN r.[ApprovedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'countNumber' THEN r.[CountNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'countNumber' THEN r.[CountNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'responsibleEmployeeId' THEN r.[ResponsibleEmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'responsibleEmployeeId' THEN r.[ResponsibleEmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
